def parse_slot(text):
    if not text.isdecimal():
        return None
    slot = int(text)
    return slot if slot < 4 else None


def describe_slot(slot, labels):
    if slot not in labels:
        return 'vacant'
    return labels[slot]


def penalty(mode, weekend, member):
    amount = 0
    if mode == 'express':
        amount += 7
    elif mode == 'bulk':
        amount += 5
    if weekend:
        amount += 3
    if member:
        amount -= 2
    return amount

